interface CreateCouponRequest {
title: unknown;
receiverId: unknown;
expiresAt: unknown;
}
function parseCreateCouponRequest(
body: unknown
): CreateCouponInput {
if (
typeof body !== "object" ||
body === null
) {
throw new Error(
"요청 본문은 객체여야 한다."
);
}
const request =
body as Record<string, unknown>;
if (typeof request.title !== "string") {
throw new Error(
"쿠폰 제목은 문자열이어야 한다."
);
}
if (
typeof request.receiverId !== "string"
) {
throw new Error(
"수신자 ID는 문자열이어야 한다."
);
}
const expiresAt =
request.expiresAt === null
? null
: new Date(String(request.expiresAt));
if (
expiresAt !== null &&
Number.isNaN(expiresAt.getTime())
) {
throw new Error(
"올바르지 않은 만료 시각이다."
);
}
return {
title: request.title.trim(),
receiverId: request.receiverId,
expiresAt,
};
}
